SELECT DISTINCTROW [9settembregen].Difetto, Sum([9settembregen].ConteggiodiCommessa) AS SommadiConteggiodiCommessa, [9settembre300].Difetto, Sum([9settembre300].ConteggiodiCommessa) AS SommadiConteggiodiCommessa1, [9settembre1000].Difetto, Sum([9settembre1000].ConteggiodiCommessa) AS SommadiConteggiodiCommessa2, [9settembre+1000].Difetto, Sum([9settembre+1000].ConteggiodiCommessa) AS SommadiConteggiodiCommessa3 INTO QualitaSettembre
FROM ((9settembregen LEFT JOIN 9settembre300 ON [9settembregen].Difetto = [9settembre300].Difetto) LEFT JOIN 9settembre1000 ON [9settembregen].Difetto = [9settembre1000].Difetto) LEFT JOIN [9settembre+1000] ON [9settembregen].Difetto = [9settembre+1000].Difetto
GROUP BY [9settembregen].Difetto, [9settembre300].Difetto, [9settembre1000].Difetto, [9settembre+1000].Difetto;
